// Catalogo delle ricette base, incluso nell'app (sola lettura).
// Generato da tools/ricette_base.py: per aggiungerne, modifica i file tools/ricette_base_*.txt
window.RICETTE_BASE = [{"id":"base-pasta-al-tonno","title":"Pasta al tonno","category":"Primi","servings":4,"servingsUnit":"porzioni","prepMin":10,"cookMin":15,"restMin":null,"difficulty":"facile","tags":["veloce","dispensa"],"ingredients":["320 g spaghetti","160 g tonno sott'olio, sgocciolato","1 spicchio d'aglio","200 g polpa di pomodoro","2 cucchiai di olio extravergine","prezzemolo q.b.","sale q.b."],"steps":["Metti a bollire l'acqua salata per la pasta.","In padella scalda l'olio con l'aglio schiacciato, toglilo quando è dorato e aggiungi la polpa di pomodoro: cuoci per 10 minuti.","Unisci il tonno sgocciolato e sbriciolato e scalda per 2 minuti.","Cuoci la pasta al dente, scolala e saltala nel sugo con un mestolino d'acqua di cottura. Completa con prezzemolo tritato."],"notes":"Versione in bianco: salta il pomodoro e aggiungi scorza di limone e capperi."},{"id":"base-pasta-al-pomodoro","title":"Pasta al pomodoro","category":"Primi","servings":4,"servingsUnit":"porzioni","prepMin":5,"cookMin":20,"restMin":null,"difficulty":"facile","tags":["veloce","vegetariano"],"ingredients":["320 g spaghetti","700 g passata di pomodoro","1 spicchio d'aglio","3 cucchiai di olio extravergine","basilico q.b.","sale q.b."],"steps":["Scalda l'olio con l'aglio in una casseruola, aggiungi la passata e un pizzico di sale.","Cuoci a fuoco dolce per 15 minuti, poi togli l'aglio e aggiungi il basilico.","Lessa la pasta al dente, scolala e mescolala al sugo."],"notes":"Con un po' di parmigiano o una mozzarella a cubetti diventa ancora più ricca."},{"id":"base-spaghetti-aglio-olio-e-peperoncino","title":"Spaghetti aglio, olio e peperoncino","category":"Primi","servings":4,"servingsUnit":"porzioni","prepMin":5,"cookMin":12,"restMin":null,"difficulty":"facile","tags":["veloce","vegano"],"ingredients":["320 g spaghetti","3 spicchi d'aglio","1 peperoncino","5 cucchiai di olio extravergine","prezzemolo q.b.","sale q.b."],"steps":["Lessa gli spaghetti in acqua salata.","Intanto scalda l'olio a fuoco dolce con l'aglio a fettine e il peperoncino, senza far bruciare l'aglio.","Scola la pasta al dente, saltala nell'olio con un po' d'acqua di cottura e completa con prezzemolo."],"notes":""},{"id":"base-spaghetti-alla-carbonara","title":"Spaghetti alla carbonara","category":"Primi","servings":4,"servingsUnit":"porzioni","prepMin":10,"cookMin":15,"restMin":null,"difficulty":"media","tags":["classico"],"ingredients":["320 g spaghetti","150 g guanciale","4 tuorli","50 g pecorino romano grattugiato","pepe nero q.b.","sale q.b."],"steps":["Taglia il guanciale a listarelle e rosolalo in padella senza olio per 8 minuti, finché è croccante.","Sbatti i tuorli con il pecorino e molto pepe.","Cuoci la pasta al dente, scolala e saltala nel grasso del guanciale a fuoco spento.","Aggiungi la crema di uova con un po' d'acqua di cottura e mescola velocemente finché diventa cremosa. Unisci il guanciale."],"notes":"Il fuoco deve essere spento quando aggiungi le uova, altrimenti si rapprendono."},{"id":"base-pasta-all-amatriciana","title":"Pasta all'amatriciana","category":"Primi","servings":4,"servingsUnit":"porzioni","prepMin":10,"cookMin":20,"restMin":null,"difficulty":"media","tags":["classico"],"ingredients":["320 g bucatini","150 g guanciale","400 g polpa di pomodoro","50 g pecorino romano grattugiato","1 peperoncino","sale q.b."],"steps":["Rosola il guanciale a listarelle in padella per 6 minuti, poi toglilo e tienilo da parte.","Nel grasso aggiungi il peperoncino e la polpa di pomodoro e cuoci per 12 minuti.","Rimetti il guanciale nel sugo.","Cuoci la pasta al dente, saltala nel sugo e completa con il pecorino."],"notes":""},{"id":"base-cacio-e-pepe","title":"Cacio e pepe","category":"Primi","servings":4,"servingsUnit":"porzioni","prepMin":5,"cookMin":12,"restMin":null,"difficulty":"media","tags":["classico","vegetariano"],"ingredients":["320 g tonnarelli","160 g pecorino romano grattugiato","pepe nero q.b.","sale q.b."],"steps":["Lessa la pasta in poca acqua salata.","Tosta il pepe macinato in padella per 1 minuto, poi aggiungi un mestolo d'acqua di cottura.","In una ciotola mescola il pecorino con un po' d'acqua di cottura tiepida fino a ottenere una crema.","Scola la pasta nella padella, toglila dal fuoco e aggiungi la crema di pecorino mescolando energicamente."],"notes":""},{"id":"base-pasta-al-pesto","title":"Pasta al pesto","category":"Primi","servings":4,"servingsUnit":"porzioni","prepMin":10,"cookMin":12,"restMin":null,"difficulty":"facile","tags":["veloce","vegetariano"],"ingredients":["320 g trofie","50 g basilico","60 g parmigiano grattugiato","20 g pecorino grattugiato","30 g pinoli","1 spicchio d'aglio","100 ml olio extravergine","sale q.b."],"steps":["Frulla basilico, pinoli, aglio e un pizzico di sale con l'olio, a scatti per non scaldare il basilico.","Aggiungi i formaggi e mescola.","Lessa la pasta, scolala tenendo un po' d'acqua di cottura e condiscila con il pesto allungato con l'acqua."],"notes":""},{"id":"base-penne-all-arrabbiata","title":"Penne all'arrabbiata","category":"Primi","servings":4,"servingsUnit":"porzioni","prepMin":5,"cookMin":20,"restMin":null,"difficulty":"facile","tags":["veloce","vegano","piccante"],"ingredients":["320 g penne","500 g pomodori pelati","2 spicchi d'aglio","2 peperoncini","3 cucchiai di olio extravergine","prezzemolo q.b.","sale q.b."],"steps":["Scalda l'olio con aglio e peperoncino tritati per 1 minuto.","Aggiungi i pelati schiacciati e cuoci per 15 minuti.","Lessa le penne al dente, saltale nel sugo e completa con prezzemolo."],"notes":""},{"id":"base-pasta-alla-norma","title":"Pasta alla Norma","category":"Primi","servings":4,"servingsUnit":"porzioni","prepMin":15,"cookMin":30,"restMin":null,"difficulty":"media","tags":["vegetariano"],"ingredients":["320 g rigatoni","2 melanzane","600 g passata di pomodoro","1 spicchio d'aglio","80 g ricotta salata grattugiata","basilico q.b.","olio per friggere q.b.","sale q.b."],"steps":["Taglia le melanzane a cubetti e friggile in olio caldo per 5 minuti, poi scolale su carta assorbente.","Cuoci la passata con aglio, un filo d'olio e sale per 15 minuti.","Lessa la pasta, condiscila con il sugo e metà delle melanzane.","Completa con le melanzane rimaste, ricotta salata e basilico."],"notes":""},{"id":"base-pasta-e-zucchine","title":"Pasta e zucchine","category":"Primi","servings":4,"servingsUnit":"porzioni","prepMin":10,"cookMin":15,"restMin":null,"difficulty":"facile","tags":["veloce","vegetariano"],"ingredients":["320 g pasta corta","3 zucchine","1 spicchio d'aglio","40 g parmigiano grattugiato","3 cucchiai di olio extravergine","basilico q.b.","sale q.b."],"steps":["Taglia le zucchine a rondelle sottili e cuocile in padella con olio e aglio per 10 minuti.","Lessa la pasta al dente.","Saltala con le zucchine, un mestolino d'acqua di cottura e il parmigiano. Completa con basilico."],"notes":""},{"id":"base-pasta-e-fagioli","title":"Pasta e fagioli","category":"Primi","servings":4,"servingsUnit":"porzioni","prepMin":10,"cookMin":30,"restMin":null,"difficulty":"facile","tags":["tradizionale"],"ingredients":["200 g ditalini","480 g fagioli borlotti lessati","1 carota","1 costa di sedano","1 cipolla","2 cucchiai di concentrato di pomodoro","1 l brodo vegetale","3 cucchiai di olio extravergine","rosmarino q.b.","sale q.b."],"steps":["Trita carota, sedano e cipolla e soffriggili nell'olio per 5 minuti.","Aggiungi fagioli, concentrato, rosmarino e brodo e cuoci per 15 minuti.","Frulla un terzo della minestra per renderla cremosa.","Aggiungi la pasta e cuocila nella minestra per 10 minuti, aggiungendo brodo se serve."],"notes":""},{"id":"base-pasta-e-ceci","title":"Pasta e ceci","category":"Primi","servings":4,"servingsUnit":"porzioni","prepMin":10,"cookMin":30,"restMin":null,"difficulty":"facile","tags":["tradizionale","vegano"],"ingredients":["200 g ditalini","480 g ceci lessati","1 spicchio d'aglio","1 rametto di rosmarino","1 l brodo vegetale","3 cucchiai di olio extravergine","sale q.b.","pepe nero q.b."],"steps":["Scalda l'olio con aglio e rosmarino, aggiungi i ceci e insaporisci per 3 minuti.","Versa il brodo e cuoci per 15 minuti, poi frulla metà dei ceci.","Aggiungi la pasta e cuocila nella minestra per 10 minuti. Completa con olio a crudo e pepe."],"notes":""},{"id":"base-pasta-e-patate","title":"Pasta e patate","category":"Primi","servings":4,"servingsUnit":"porzioni","prepMin":10,"cookMin":30,"restMin":null,"difficulty":"facile","tags":["tradizionale"],"ingredients":["250 g pasta mista","600 g patate","1 cipolla","1 costa di sedano","1 carota","1 cucchiaio di concentrato di pomodoro","1 l brodo vegetale","60 g provola a cubetti","3 cucchiai di olio extravergine","sale q.b."],"steps":["Soffriggi cipolla, sedano e carota tritati nell'olio per 5 minuti.","Aggiungi le patate a cubetti e il concentrato, poi copri con il brodo e cuoci per 15 minuti.","Aggiungi la pasta e cuocila mescolando spesso per 10 minuti.","A fuoco spento unisci la provola e lascia riposare 2 minuti."],"notes":""},{"id":"base-lasagne-alla-bolognese","title":"Lasagne alla bolognese","category":"Primi","servings":6,"servingsUnit":"porzioni","prepMin":40,"cookMin":40,"restMin":10,"difficulty":"media","tags":["festa","forno"],"ingredients":["300 g sfoglie per lasagne","400 g macinato misto","700 g passata di pomodoro","1 carota","1 costa di sedano","1 cipolla","100 ml vino rosso","800 ml besciamella","100 g parmigiano grattugiato","3 cucchiai di olio extravergine","sale q.b."],"steps":["Soffriggi carota, sedano e cipolla tritati nell'olio, aggiungi il macinato e rosolalo per 5 minuti.","Sfuma con il vino, aggiungi la passata e cuoci il ragù a fuoco basso per 40 minuti.","In una teglia alterna strati di sfoglia, ragù, besciamella e parmigiano.","Termina con besciamella e parmigiano e inforna a 180 °C per 40 minuti.","Lascia riposare 10 minuti prima di tagliare."],"notes":"Per un ragù più saporito cuocilo anche 2 ore: puoi prepararlo il giorno prima."},{"id":"base-tagliatelle-al-ragu","title":"Tagliatelle al ragù","category":"Primi","servings":4,"servingsUnit":"porzioni","prepMin":15,"cookMin":120,"restMin":null,"difficulty":"media","tags":["classico"],"ingredients":["400 g tagliatelle","300 g macinato misto","1 carota","1 costa di sedano","1 cipolla","100 ml vino rosso","500 g passata di pomodoro","3 cucchiai di olio extravergine","parmigiano q.b.","sale q.b."],"steps":["Soffriggi il trito di verdure nell'olio per 5 minuti, poi rosola la carne.","Sfuma con il vino, aggiungi la passata e cuoci coperto a fuoco minimo per 2 ore, mescolando ogni tanto.","Lessa le tagliatelle, condiscile con il ragù e servi con parmigiano."],"notes":""},{"id":"base-gnocchi-al-pomodoro","title":"Gnocchi al pomodoro","category":"Primi","servings":4,"servingsUnit":"porzioni","prepMin":5,"cookMin":20,"restMin":null,"difficulty":"facile","tags":["veloce","vegetariano"],"ingredients":["800 g gnocchi di patate","500 g passata di pomodoro","1 spicchio d'aglio","1 mozzarella","3 cucchiai di olio extravergine","basilico q.b.","sale q.b."],"steps":["Cuoci la passata con olio, aglio e sale per 15 minuti.","Lessa gli gnocchi in acqua salata e scolali quando vengono a galla.","Saltali nel sugo con la mozzarella a cubetti e il basilico."],"notes":""},{"id":"base-risotto-alla-parmigiana","title":"Risotto alla parmigiana","category":"Primi","servings":4,"servingsUnit":"porzioni","prepMin":5,"cookMin":20,"restMin":null,"difficulty":"facile","tags":["vegetariano"],"ingredients":["320 g riso carnaroli","1 cipolla","1,2 l brodo vegetale","80 ml vino bianco","60 g burro","80 g parmigiano grattugiato","sale q.b."],"steps":["Fai appassire la cipolla tritata in metà burro, poi tosta il riso per 2 minuti.","Sfuma con il vino e porta a cottura aggiungendo brodo caldo poco alla volta per 18 minuti.","A fuoco spento manteca con il burro rimasto e il parmigiano e lascia riposare 1 minuto."],"notes":""},{"id":"base-risotto-ai-funghi","title":"Risotto ai funghi","category":"Primi","servings":4,"servingsUnit":"porzioni","prepMin":10,"cookMin":20,"restMin":null,"difficulty":"media","tags":["vegetariano"],"ingredients":["320 g riso carnaroli","300 g funghi champignon","1 scalogno","1 spicchio d'aglio","1,2 l brodo vegetale","80 ml vino bianco","40 g burro","60 g parmigiano grattugiato","2 cucchiai di olio extravergine","prezzemolo q.b.","sale q.b."],"steps":["Trifola i funghi con olio e aglio per 8 minuti.","In un'altra pentola fai appassire lo scalogno in metà burro e tosta il riso.","Sfuma con il vino e cuoci aggiungendo brodo caldo per 18 minuti; a metà cottura unisci i funghi.","Manteca con il burro rimasto, il parmigiano e il prezzemolo."],"notes":""},{"id":"base-risotto-alla-milanese","title":"Risotto alla milanese","category":"Primi","servings":4,"servingsUnit":"porzioni","prepMin":5,"cookMin":20,"restMin":null,"difficulty":"media","tags":["classico","vegetariano"],"ingredients":["320 g riso carnaroli","1 cipolla","1 bustina di zafferano","1,2 l brodo di carne","80 ml vino bianco","60 g burro","80 g parmigiano grattugiato","sale q.b."],"steps":["Fai appassire la cipolla in metà burro e tosta il riso.","Sfuma con il vino e cuoci con il brodo caldo per 18 minuti; a metà aggiungi lo zafferano sciolto in un po' di brodo.","Manteca con il burro rimasto e il parmigiano."],"notes":""},{"id":"base-risotto-alla-zucca","title":"Risotto alla zucca","category":"Primi","servings":4,"servingsUnit":"porzioni","prepMin":15,"cookMin":25,"restMin":null,"difficulty":"facile","tags":["vegetariano","autunno"],"ingredients":["320 g riso carnaroli","500 g zucca","1 cipolla","1,2 l brodo vegetale","40 g burro","60 g parmigiano grattugiato","2 cucchiai di olio extravergine","rosmarino q.b.","sale q.b."],"steps":["Cuoci la zucca a cubetti con olio, cipolla e un mestolo di brodo per 10 minuti.","Aggiungi il riso, tostalo 1 minuto e porta a cottura con il brodo caldo per 18 minuti.","Manteca con burro, parmigiano e un po' di rosmarino tritato."],"notes":""},{"id":"base-riso-in-bianco","title":"Riso in bianco","category":"Primi","servings":2,"servingsUnit":"porzioni","prepMin":2,"cookMin":15,"restMin":null,"difficulty":"facile","tags":["veloce","leggero"],"ingredients":["160 g riso","20 g burro","30 g parmigiano grattugiato","sale q.b."],"steps":["Lessa il riso in abbondante acqua salata per il tempo indicato sulla confezione, circa 15 minuti.","Scolalo e condiscilo con burro e parmigiano."],"notes":""},{"id":"base-insalata-di-riso","title":"Insalata di riso","category":"Piatti unici","servings":6,"servingsUnit":"porzioni","prepMin":25,"cookMin":15,"restMin":30,"difficulty":"facile","tags":["estate","freddo"],"ingredients":["400 g riso","200 g tonno sott'olio","150 g prosciutto cotto a cubetti","150 g emmental a cubetti","4 uova sode","200 g mais","150 g piselli","100 g olive verdi","4 cucchiai di olio extravergine","sale q.b."],"steps":["Lessa il riso al dente per 15 minuti, scolalo e raffreddalo sotto l'acqua corrente.","Rassoda le uova per 9 minuti e tagliale a pezzi.","Unisci al riso tutti gli altri ingredienti e condisci con olio e sale.","Fai riposare in frigo almeno 30 minuti prima di servire."],"notes":""},{"id":"base-insalata-di-pasta","title":"Insalata di pasta","category":"Piatti unici","servings":4,"servingsUnit":"porzioni","prepMin":15,"cookMin":12,"restMin":20,"difficulty":"facile","tags":["estate","freddo"],"ingredients":["320 g fusilli","250 g pomodorini","1 mozzarella","80 g olive nere","120 g tonno sott'olio","4 cucchiai di olio extravergine","basilico q.b.","origano q.b.","sale q.b."],"steps":["Lessa la pasta al dente, scolala e passala sotto l'acqua fredda.","Taglia pomodorini e mozzarella a pezzetti.","Unisci tutto alla pasta con tonno e olive e condisci con olio, sale, origano e basilico.","Lascia riposare in frigo 20 minuti."],"notes":""},{"id":"base-minestrone-di-verdure","title":"Minestrone di verdure","category":"Primi","servings":6,"servingsUnit":"porzioni","prepMin":20,"cookMin":40,"restMin":null,"difficulty":"facile","tags":["vegano","leggero"],"ingredients":["2 patate","2 carote","2 zucchine","1 costa di sedano","1 cipolla","150 g fagiolini","200 g piselli","240 g fagioli cannellini lessati","2 pomodori","1,5 l brodo vegetale","3 cucchiai di olio extravergine","sale q.b."],"steps":["Taglia tutte le verdure a cubetti piccoli.","Soffriggi cipolla e sedano nell'olio per 3 minuti, poi aggiungi le altre verdure.","Copri con il brodo e cuoci a fuoco medio per 40 minuti.","Aggiungi i fagioli negli ultimi 10 minuti e servi con un filo d'olio a crudo."],"notes":"Puoi aggiungere 150 g di pastina o riso negli ultimi 10 minuti."},{"id":"base-vellutata-di-zucca","title":"Vellutata di zucca","category":"Primi","servings":4,"servingsUnit":"porzioni","prepMin":15,"cookMin":25,"restMin":null,"difficulty":"facile","tags":["vegetariano","autunno"],"ingredients":["800 g zucca","1 patata","1 cipolla","800 ml brodo vegetale","2 cucchiai di olio extravergine","noce moscata q.b.","sale q.b."],"steps":["Soffriggi la cipolla nell'olio, aggiungi zucca e patata a cubetti.","Copri con il brodo e cuoci per 25 minuti.","Frulla fino a ottenere una crema e regola di sale e noce moscata."],"notes":""},{"id":"base-pastina-in-brodo","title":"Pastina in brodo","category":"Primi","servings":2,"servingsUnit":"porzioni","prepMin":2,"cookMin":10,"restMin":null,"difficulty":"facile","tags":["veloce","leggero"],"ingredients":["100 g pastina","800 ml brodo vegetale","30 g parmigiano grattugiato"],"steps":["Porta il brodo a bollore.","Aggiungi la pastina e cuocila per 6-8 minuti.","Servi con parmigiano."],"notes":""},{"id":"base-frittata","title":"Frittata","category":"Secondi","servings":4,"servingsUnit":"porzioni","prepMin":5,"cookMin":10,"restMin":null,"difficulty":"facile","tags":["veloce","uova","vegetariano"],"ingredients":["6 uova","40 g parmigiano grattugiato","2 cucchiai di latte","2 cucchiai di olio extravergine","sale q.b.","pepe nero q.b."],"steps":["Sbatti le uova con parmigiano, latte, sale e pepe.","Scalda l'olio in una padella antiaderente e versa le uova.","Cuoci a fuoco medio-basso coperto per 6 minuti, poi gira la frittata aiutandoti con un piatto e cuoci altri 3 minuti."],"notes":""},{"id":"base-frittata-di-zucchine","title":"Frittata di zucchine","category":"Secondi","servings":4,"servingsUnit":"porzioni","prepMin":10,"cookMin":15,"restMin":null,"difficulty":"facile","tags":["uova","vegetariano"],"ingredients":["6 uova","2 zucchine","1 cipollotto","40 g parmigiano grattugiato","2 cucchiai di olio extravergine","sale q.b."],"steps":["Cuoci le zucchine a rondelle con olio e cipollotto per 8 minuti.","Sbatti le uova con parmigiano e sale e aggiungi le zucchine.","Cuoci in padella coperta per 6 minuti per lato."],"notes":""},{"id":"base-frittata-di-patate","title":"Frittata di patate","category":"Secondi","servings":4,"servingsUnit":"porzioni","prepMin":10,"cookMin":25,"restMin":null,"difficulty":"facile","tags":["uova","vegetariano"],"ingredients":["6 uova","400 g patate","1 cipolla","40 g parmigiano grattugiato","3 cucchiai di olio extravergine","sale q.b."],"steps":["Taglia le patate a fettine sottili e cuocile in padella con olio e cipolla per 15 minuti.","Sbatti le uova con il parmigiano e il sale e versale sulle patate.","Cuoci coperto per 5 minuti, gira e cuoci altri 4 minuti."],"notes":""},{"id":"base-uova-al-tegamino","title":"Uova al tegamino","category":"Secondi","servings":2,"servingsUnit":"porzioni","prepMin":1,"cookMin":5,"restMin":null,"difficulty":"facile","tags":["veloce","uova"],"ingredients":["4 uova","10 g burro","sale q.b."],"steps":["Sciogli il burro in un padellino.","Rompi le uova e cuocile a fuoco medio per 4 minuti, finché l'albume è rappreso e il tuorlo ancora morbido.","Sala e servi subito."],"notes":""},{"id":"base-uova-strapazzate","title":"Uova strapazzate","category":"Colazione","servings":2,"servingsUnit":"porzioni","prepMin":2,"cookMin":4,"restMin":null,"difficulty":"facile","tags":["veloce","uova"],"ingredients":["4 uova","2 cucchiai di latte","10 g burro","sale q.b.","pepe nero q.b."],"steps":["Sbatti leggermente le uova con latte, sale e pepe.","Sciogli il burro a fuoco basso e versa le uova.","Mescola delicatamente con una spatola per 3 minuti e togli dal fuoco quando sono ancora cremose."],"notes":""},{"id":"base-uova-sode","title":"Uova sode","category":"Secondi","servings":4,"servingsUnit":"porzioni","prepMin":1,"cookMin":9,"restMin":null,"difficulty":"facile","tags":["uova"],"ingredients":["4 uova","sale q.b."],"steps":["Metti le uova in un pentolino, coprile d'acqua fredda e porta a bollore.","Dal bollore cuoci per 9 minuti.","Raffreddale in acqua fredda e sgusciale."],"notes":""},{"id":"base-uova-in-camicia","title":"Uova in camicia","category":"Colazione","servings":2,"servingsUnit":"porzioni","prepMin":2,"cookMin":4,"restMin":null,"difficulty":"media","tags":["uova"],"ingredients":["4 uova","1 cucchiaio di aceto","sale q.b."],"steps":["Porta a leggero bollore una pentola d'acqua con l'aceto.","Crea un vortice con un cucchiaio e fai scivolare dentro un uovo alla volta.","Cuoci per 3 minuti e scola con una schiumarola."],"notes":""},{"id":"base-omelette-al-formaggio","title":"Omelette al formaggio","category":"Secondi","servings":1,"servingsUnit":"porzioni","prepMin":3,"cookMin":4,"restMin":null,"difficulty":"facile","tags":["veloce","uova","vegetariano"],"ingredients":["3 uova","40 g emmental grattugiato","10 g burro","sale q.b."],"steps":["Sbatti le uova con un pizzico di sale.","Sciogli il burro in padella, versa le uova e cuoci per 2 minuti muovendo la padella.","Distribuisci il formaggio su metà, ripiega e cuoci ancora 1 minuto."],"notes":""},{"id":"base-uova-al-pomodoro","title":"Uova al pomodoro","category":"Secondi","servings":4,"servingsUnit":"porzioni","prepMin":5,"cookMin":20,"restMin":null,"difficulty":"facile","tags":["uova","vegetariano"],"ingredients":["6 uova","500 g passata di pomodoro","1 spicchio d'aglio","2 cucchiai di olio extravergine","basilico q.b.","sale q.b."],"steps":["Cuoci la passata con olio, aglio e sale per 10 minuti.","Fai sei incavi nel sugo e rompi dentro le uova.","Copri e cuoci per 8 minuti, finché l'albume è rappreso. Completa con basilico."],"notes":""},{"id":"base-petto-di-pollo-alla-piastra","title":"Petto di pollo alla piastra","category":"Secondi","servings":2,"servingsUnit":"porzioni","prepMin":5,"cookMin":10,"restMin":null,"difficulty":"facile","tags":["veloce","leggero"],"ingredients":["400 g petto di pollo","2 cucchiai di olio extravergine","1 limone","rosmarino q.b.","sale q.b."],"steps":["Batti leggermente le fette di pollo per renderle uniformi.","Ungi con poco olio e cuoci su una piastra ben calda per 4 minuti per lato.","Condisci con sale, rosmarino e succo di limone."],"notes":""},{"id":"base-scaloppine-al-limone","title":"Scaloppine al limone","category":"Secondi","servings":4,"servingsUnit":"porzioni","prepMin":10,"cookMin":10,"restMin":null,"difficulty":"facile","tags":["veloce"],"ingredients":["500 g fettine di vitello","50 g farina","40 g burro","1 limone","prezzemolo q.b.","sale q.b."],"steps":["Infarina le fettine e scuoti l'eccesso.","Rosolale nel burro per 2 minuti per lato.","Aggiungi il succo di limone e un po' d'acqua, fai addensare per 1 minuto e completa con prezzemolo e sale."],"notes":""},{"id":"base-cotolette-alla-milanese","title":"Cotolette alla milanese","category":"Secondi","servings":4,"servingsUnit":"porzioni","prepMin":15,"cookMin":10,"restMin":null,"difficulty":"facile","tags":["fritto"],"ingredients":["4 cotolette di vitello","2 uova","150 g pangrattato","80 g burro","sale q.b."],"steps":["Passa le cotolette nell'uovo sbattuto e poi nel pangrattato, premendo bene.","Cuocile nel burro spumeggiante per 4 minuti per lato.","Scolale su carta assorbente e sala."],"notes":""},{"id":"base-cotolette-di-pollo-al-forno","title":"Cotolette di pollo al forno","category":"Secondi","servings":4,"servingsUnit":"porzioni","prepMin":15,"cookMin":20,"restMin":null,"difficulty":"facile","tags":["forno"],"ingredients":["500 g petto di pollo a fette","2 uova","120 g pangrattato","30 g parmigiano grattugiato","2 cucchiai di olio extravergine","sale q.b."],"steps":["Mescola pangrattato e parmigiano.","Passa il pollo nell'uovo sbattuto con il sale e poi nella panatura.","Disponi su teglia con carta forno, condisci con un filo d'olio e cuoci a 200 °C per 20 minuti, girando a metà."],"notes":""},{"id":"base-pollo-al-forno-con-patate","title":"Pollo al forno con patate","category":"Secondi","servings":4,"servingsUnit":"porzioni","prepMin":15,"cookMin":60,"restMin":null,"difficulty":"facile","tags":["forno","domenica"],"ingredients":["1 kg cosce di pollo","800 g patate","2 spicchi d'aglio","4 cucchiai di olio extravergine","rosmarino q.b.","sale q.b.","pepe nero q.b."],"steps":["Taglia le patate a spicchi e mettile in teglia con il pollo, l'aglio e il rosmarino.","Condisci con olio, sale e pepe e mescola bene.","Cuoci a 200 °C per 60 minuti, girando a metà cottura."],"notes":""},{"id":"base-polpette-al-sugo","title":"Polpette al sugo","category":"Secondi","servings":4,"servingsUnit":"porzioni","prepMin":25,"cookMin":30,"restMin":null,"difficulty":"media","tags":["tradizionale"],"ingredients":["500 g macinato di manzo","1 uovo","50 g parmigiano grattugiato","80 g pane raffermo","100 ml latte","700 g passata di pomodoro","1 spicchio d'aglio","3 cucchiai di olio extravergine","prezzemolo q.b.","sale q.b."],"steps":["Ammolla il pane nel latte e strizzalo.","Impasta carne, pane, uovo, parmigiano, prezzemolo e sale e forma delle polpette.","Cuoci la passata con olio e aglio per 5 minuti, poi aggiungi le polpette.","Cuoci a fuoco basso coperto per 25 minuti, girandole a metà."],"notes":""},{"id":"base-hamburger-in-padella","title":"Hamburger in padella","category":"Secondi","servings":4,"servingsUnit":"porzioni","prepMin":10,"cookMin":10,"restMin":null,"difficulty":"facile","tags":["veloce"],"ingredients":["500 g macinato di manzo","1 cucchiaio di olio extravergine","sale q.b.","pepe nero q.b."],"steps":["Forma 4 hamburger compattando bene la carne.","Scalda una padella con poco olio e cuoci per 4 minuti per lato.","Sala e pepa solo alla fine."],"notes":""},{"id":"base-bistecca-ai-ferri","title":"Bistecca ai ferri","category":"Secondi","servings":2,"servingsUnit":"porzioni","prepMin":2,"cookMin":8,"restMin":5,"difficulty":"facile","tags":["veloce"],"ingredients":["2 bistecche di manzo","1 cucchiaio di olio extravergine","sale grosso q.b.","rosmarino q.b."],"steps":["Togli la carne dal frigo 30 minuti prima.","Cuocila su una piastra rovente per 3-4 minuti per lato, secondo il grado di cottura.","Fai riposare 5 minuti, poi condisci con sale grosso, olio e rosmarino."],"notes":""},{"id":"base-spezzatino-con-patate","title":"Spezzatino con patate","category":"Secondi","servings":4,"servingsUnit":"porzioni","prepMin":20,"cookMin":90,"restMin":null,"difficulty":"media","tags":["inverno"],"ingredients":["800 g spezzatino di manzo","600 g patate","1 cipolla","1 carota","1 costa di sedano","200 ml vino rosso","2 cucchiai di concentrato di pomodoro","500 ml brodo di carne","3 cucchiai di olio extravergine","sale q.b."],"steps":["Rosola la carne nell'olio a fuoco vivace, poi aggiungi il trito di verdure.","Sfuma con il vino, aggiungi concentrato e brodo e cuoci coperto per 60 minuti.","Aggiungi le patate a pezzi e cuoci altri 30 minuti."],"notes":""},{"id":"base-arrosto-di-maiale-al-forno","title":"Arrosto di maiale al forno","category":"Secondi","servings":6,"servingsUnit":"porzioni","prepMin":15,"cookMin":70,"restMin":10,"difficulty":"media","tags":["forno","domenica"],"ingredients":["1 kg lonza di maiale","2 spicchi d'aglio","150 ml vino bianco","3 cucchiai di olio extravergine","rosmarino q.b.","salvia q.b.","sale q.b."],"steps":["Massaggia la carne con sale, aglio ed erbe tritate e legala.","Rosolala in una teglia con l'olio su tutti i lati.","Sfuma con il vino e cuoci in forno a 180 °C per 70 minuti, bagnando con il fondo.","Lascia riposare 10 minuti prima di affettare."],"notes":""},{"id":"base-salsicce-e-friarielli","title":"Salsicce e friarielli","category":"Secondi","servings":4,"servingsUnit":"porzioni","prepMin":10,"cookMin":25,"restMin":null,"difficulty":"facile","tags":["tradizionale"],"ingredients":["8 salsicce","1 kg friarielli","2 spicchi d'aglio","1 peperoncino","3 cucchiai di olio extravergine","sale q.b."],"steps":["Lava i friarielli e saltali in padella con olio, aglio e peperoncino per 15 minuti.","In un'altra padella cuoci le salsicce bucherellate per 15 minuti.","Unisci tutto e fai insaporire per 5 minuti."],"notes":""},{"id":"base-saltimbocca-alla-romana","title":"Saltimbocca alla romana","category":"Secondi","servings":4,"servingsUnit":"porzioni","prepMin":15,"cookMin":8,"restMin":null,"difficulty":"facile","tags":["classico"],"ingredients":["8 fettine di vitello","8 fette di prosciutto crudo","8 foglie di salvia","30 g farina","40 g burro","80 ml vino bianco","sale q.b."],"steps":["Su ogni fettina metti una fetta di prosciutto e una foglia di salvia e fissale con uno stecchino.","Infarina il lato della carne e rosola nel burro per 2 minuti per lato.","Sfuma con il vino e fai addensare il fondo per 1 minuto."],"notes":""},{"id":"base-salmone-al-forno","title":"Salmone al forno","category":"Secondi","servings":4,"servingsUnit":"porzioni","prepMin":5,"cookMin":15,"restMin":null,"difficulty":"facile","tags":["pesce","leggero"],"ingredients":["600 g filetto di salmone","1 limone","2 cucchiai di olio extravergine","aneto q.b.","sale q.b."],"steps":["Disponi il salmone in una teglia con carta forno.","Condisci con olio, sale, aneto e fettine di limone.","Cuoci a 200 °C per 15 minuti."],"notes":""},{"id":"base-merluzzo-al-pomodoro","title":"Merluzzo al pomodoro","category":"Secondi","servings":4,"servingsUnit":"porzioni","prepMin":10,"cookMin":20,"restMin":null,"difficulty":"facile","tags":["pesce"],"ingredients":["600 g filetti di merluzzo","400 g pomodorini","1 spicchio d'aglio","30 g olive nere","1 cucchiaio di capperi","3 cucchiai di olio extravergine","prezzemolo q.b.","sale q.b."],"steps":["Scalda olio e aglio, aggiungi i pomodorini tagliati e cuoci per 8 minuti.","Unisci olive e capperi, poi adagia i filetti nel sugo.","Copri e cuoci per 10 minuti. Completa con prezzemolo."],"notes":""},{"id":"base-orata-al-forno","title":"Orata al forno","category":"Secondi","servings":2,"servingsUnit":"porzioni","prepMin":10,"cookMin":25,"restMin":null,"difficulty":"facile","tags":["pesce"],"ingredients":["2 orate pulite","1 limone","2 spicchi d'aglio","3 cucchiai di olio extravergine","prezzemolo q.b.","sale q.b."],"steps":["Farcisci le orate con fette di limone, aglio e prezzemolo.","Mettile in teglia, condisci con olio e sale.","Cuoci a 200 °C per 25 minuti."],"notes":""},{"id":"base-gamberi-in-padella","title":"Gamberi in padella","category":"Secondi","servings":4,"servingsUnit":"porzioni","prepMin":10,"cookMin":6,"restMin":null,"difficulty":"facile","tags":["pesce","veloce"],"ingredients":["600 g gamberi","2 spicchi d'aglio","80 ml vino bianco","3 cucchiai di olio extravergine","prezzemolo q.b.","sale q.b."],"steps":["Scalda olio e aglio in padella.","Aggiungi i gamberi e cuocili per 2 minuti, poi sfuma con il vino.","Cuoci altri 3 minuti e completa con prezzemolo."],"notes":""},{"id":"base-tonno-in-padella","title":"Tonno in padella","category":"Secondi","servings":2,"servingsUnit":"porzioni","prepMin":5,"cookMin":4,"restMin":null,"difficulty":"facile","tags":["pesce","veloce"],"ingredients":["2 tranci di tonno fresco","2 cucchiai di semi di sesamo","1 cucchiaio di olio extravergine","sale q.b."],"steps":["Passa i tranci nel sesamo.","Scotta in padella rovente con poco olio per 1-2 minuti per lato, lasciando l'interno rosato.","Sala e servi a fette."],"notes":""},{"id":"base-cozze-alla-marinara","title":"Cozze alla marinara","category":"Secondi","servings":4,"servingsUnit":"porzioni","prepMin":20,"cookMin":10,"restMin":null,"difficulty":"facile","tags":["pesce"],"ingredients":["1,5 kg cozze","2 spicchi d'aglio","3 cucchiai di olio extravergine","prezzemolo q.b.","pepe nero q.b."],"steps":["Pulisci bene le cozze sotto l'acqua corrente.","In una pentola larga scalda olio e aglio, aggiungi le cozze e copri.","Cuoci per 5-6 minuti, finché si aprono. Completa con prezzemolo e pepe."],"notes":""},{"id":"base-calamari-fritti","title":"Calamari fritti","category":"Secondi","servings":4,"servingsUnit":"porzioni","prepMin":15,"cookMin":8,"restMin":null,"difficulty":"media","tags":["pesce","fritto"],"ingredients":["600 g anelli di calamaro","100 g farina","olio per friggere q.b.","1 limone","sale q.b."],"steps":["Asciuga bene i calamari e infarinali.","Friggili in olio a 175 °C per 2-3 minuti, pochi alla volta.","Scolali, sala e servi con spicchi di limone."],"notes":""},{"id":"base-polpo-con-patate","title":"Polpo con patate","category":"Secondi","servings":4,"servingsUnit":"porzioni","prepMin":15,"cookMin":50,"restMin":null,"difficulty":"media","tags":["pesce"],"ingredients":["1 kg polpo","600 g patate","1 limone","4 cucchiai di olio extravergine","prezzemolo q.b.","sale q.b."],"steps":["Cuoci il polpo in acqua bollente per 45 minuti e lascialo intiepidire nella sua acqua.","Lessa le patate a pezzi per 15 minuti.","Taglia il polpo e condisci tutto con olio, limone, prezzemolo e sale."],"notes":""},{"id":"base-insalata-mista","title":"Insalata mista","category":"Contorni","servings":4,"servingsUnit":"porzioni","prepMin":10,"cookMin":null,"restMin":null,"difficulty":"facile","tags":["veloce","vegano","leggero"],"ingredients":["200 g insalata","2 pomodori","1 carota","1 cetriolo","3 cucchiai di olio extravergine","1 cucchiaio di aceto","sale q.b."],"steps":["Lava e asciuga l'insalata.","Taglia pomodori e cetriolo a pezzi e grattugia la carota.","Condisci con olio, aceto e sale appena prima di servire."],"notes":""},{"id":"base-insalata-caprese","title":"Insalata caprese","category":"Antipasti","servings":4,"servingsUnit":"porzioni","prepMin":10,"cookMin":null,"restMin":null,"difficulty":"facile","tags":["estate","vegetariano"],"ingredients":["3 pomodori","2 mozzarelle","3 cucchiai di olio extravergine","basilico q.b.","origano q.b.","sale q.b."],"steps":["Taglia pomodori e mozzarella a fette.","Alternali su un piatto.","Condisci con olio, sale, origano e basilico."],"notes":""},{"id":"base-insalata-di-pollo","title":"Insalata di pollo","category":"Piatti unici","servings":2,"servingsUnit":"porzioni","prepMin":15,"cookMin":10,"restMin":null,"difficulty":"facile","tags":["leggero"],"ingredients":["300 g petto di pollo","150 g insalata","150 g pomodorini","100 g mais","3 cucchiai di olio extravergine","1 limone","sale q.b."],"steps":["Cuoci il pollo alla piastra per 4 minuti per lato e taglialo a strisce.","Unisci insalata, pomodorini e mais.","Condisci con olio, limone e sale e aggiungi il pollo."],"notes":""},{"id":"base-insalata-greca","title":"Insalata greca","category":"Piatti unici","servings":4,"servingsUnit":"porzioni","prepMin":15,"cookMin":null,"restMin":null,"difficulty":"facile","tags":["estate","vegetariano"],"ingredients":["4 pomodori","1 cetriolo","1 cipolla rossa","1 peperone verde","200 g feta","80 g olive nere","4 cucchiai di olio extravergine","origano q.b.","sale q.b."],"steps":["Taglia le verdure a pezzi grossi e la cipolla ad anelli.","Aggiungi olive e la feta a cubetti.","Condisci con olio, origano e un pizzico di sale."],"notes":""},{"id":"base-insalata-di-tonno-e-fagioli","title":"Insalata di tonno e fagioli","category":"Piatti unici","servings":4,"servingsUnit":"porzioni","prepMin":10,"cookMin":null,"restMin":null,"difficulty":"facile","tags":["veloce","dispensa"],"ingredients":["480 g fagioli cannellini lessati","160 g tonno sott'olio","1 cipolla rossa","3 cucchiai di olio extravergine","1 cucchiaio di aceto","prezzemolo q.b.","sale q.b."],"steps":["Sciacqua e scola i fagioli.","Aggiungi il tonno sgocciolato e la cipolla a fettine sottili.","Condisci con olio, aceto, sale e prezzemolo."],"notes":""},{"id":"base-insalata-di-ceci","title":"Insalata di ceci","category":"Piatti unici","servings":4,"servingsUnit":"porzioni","prepMin":10,"cookMin":null,"restMin":null,"difficulty":"facile","tags":["veloce","vegano"],"ingredients":["480 g ceci lessati","200 g pomodorini","1 cetriolo","1 cipollotto","3 cucchiai di olio extravergine","1 limone","prezzemolo q.b.","sale q.b."],"steps":["Sciacqua i ceci e scolali.","Taglia pomodorini, cetriolo e cipollotto.","Condisci con olio, succo di limone, sale e prezzemolo."],"notes":""},{"id":"base-patate-al-forno","title":"Patate al forno","category":"Contorni","servings":4,"servingsUnit":"porzioni","prepMin":10,"cookMin":45,"restMin":null,"difficulty":"facile","tags":["forno","vegano"],"ingredients":["1 kg patate","4 cucchiai di olio extravergine","2 spicchi d'aglio","rosmarino q.b.","sale q.b."],"steps":["Taglia le patate a spicchi, sciacquale e asciugale.","Condisci in teglia con olio, aglio, rosmarino e sale.","Cuoci a 200 °C per 45 minuti, girandole a metà."],"notes":""},{"id":"base-pure-di-patate","title":"Purè di patate","category":"Contorni","servings":4,"servingsUnit":"porzioni","prepMin":10,"cookMin":25,"restMin":null,"difficulty":"facile","tags":["vegetariano"],"ingredients":["1 kg patate","250 ml latte","50 g burro","30 g parmigiano grattugiato","noce moscata q.b.","sale q.b."],"steps":["Lessa le patate con la buccia per 25 minuti, poi pelale e schiacciale.","Scalda il latte e aggiungilo poco alla volta mescolando.","Unisci burro, parmigiano, sale e noce moscata."],"notes":""},{"id":"base-patate-lesse","title":"Patate lesse","category":"Contorni","servings":4,"servingsUnit":"porzioni","prepMin":5,"cookMin":25,"restMin":null,"difficulty":"facile","tags":["vegano","leggero"],"ingredients":["800 g patate","3 cucchiai di olio extravergine","prezzemolo q.b.","sale q.b."],"steps":["Lessa le patate con la buccia in acqua salata per 25 minuti.","Pelale, tagliale a pezzi e condiscile con olio, sale e prezzemolo."],"notes":""},{"id":"base-zucchine-trifolate","title":"Zucchine trifolate","category":"Contorni","servings":4,"servingsUnit":"porzioni","prepMin":10,"cookMin":15,"restMin":null,"difficulty":"facile","tags":["veloce","vegano"],"ingredients":["600 g zucchine","1 spicchio d'aglio","3 cucchiai di olio extravergine","prezzemolo q.b.","sale q.b."],"steps":["Taglia le zucchine a rondelle.","Cuocile in padella con olio e aglio a fuoco vivace per 12 minuti.","Sala e completa con prezzemolo."],"notes":""},{"id":"base-spinaci-in-padella","title":"Spinaci in padella","category":"Contorni","servings":4,"servingsUnit":"porzioni","prepMin":5,"cookMin":8,"restMin":null,"difficulty":"facile","tags":["veloce","vegano"],"ingredients":["800 g spinaci","1 spicchio d'aglio","2 cucchiai di olio extravergine","sale q.b."],"steps":["Lava gli spinaci e mettili in padella con l'acqua rimasta sulle foglie.","Quando sono appassiti aggiungi olio e aglio e cuoci per 5 minuti.","Sala e servi."],"notes":""},{"id":"base-verdure-grigliate","title":"Verdure grigliate","category":"Contorni","servings":4,"servingsUnit":"porzioni","prepMin":15,"cookMin":20,"restMin":null,"difficulty":"facile","tags":["vegano","estate"],"ingredients":["2 zucchine","2 melanzane","2 peperoni","4 cucchiai di olio extravergine","menta q.b.","sale q.b."],"steps":["Taglia le verdure a fette di mezzo centimetro.","Grigliale su una piastra rovente per 3-4 minuti per lato.","Condisci con olio, sale e menta."],"notes":""},{"id":"base-peperonata","title":"Peperonata","category":"Contorni","servings":4,"servingsUnit":"porzioni","prepMin":15,"cookMin":35,"restMin":null,"difficulty":"facile","tags":["vegano"],"ingredients":["4 peperoni","1 cipolla","300 g pomodori pelati","3 cucchiai di olio extravergine","sale q.b."],"steps":["Taglia i peperoni a strisce e la cipolla a fette.","Soffriggili nell'olio per 10 minuti.","Aggiungi i pelati e cuoci coperto per 25 minuti."],"notes":""},{"id":"base-fagiolini-all-olio","title":"Fagiolini all'olio","category":"Contorni","servings":4,"servingsUnit":"porzioni","prepMin":10,"cookMin":10,"restMin":null,"difficulty":"facile","tags":["vegano","leggero"],"ingredients":["500 g fagiolini","3 cucchiai di olio extravergine","1 limone","sale q.b."],"steps":["Spunta i fagiolini e lessali in acqua salata per 10 minuti.","Raffreddali in acqua fredda per mantenere il colore.","Condisci con olio, limone e sale."],"notes":""},{"id":"base-carote-in-padella","title":"Carote in padella","category":"Contorni","servings":4,"servingsUnit":"porzioni","prepMin":10,"cookMin":15,"restMin":null,"difficulty":"facile","tags":["vegano"],"ingredients":["600 g carote","20 g burro","1 cucchiaino di zucchero","prezzemolo q.b.","sale q.b."],"steps":["Taglia le carote a rondelle.","Cuocile in padella con burro, zucchero e un po' d'acqua per 15 minuti, finché sono glassate.","Sala e completa con prezzemolo."],"notes":""},{"id":"base-funghi-trifolati","title":"Funghi trifolati","category":"Contorni","servings":4,"servingsUnit":"porzioni","prepMin":10,"cookMin":15,"restMin":null,"difficulty":"facile","tags":["vegano"],"ingredients":["500 g funghi champignon","2 spicchi d'aglio","3 cucchiai di olio extravergine","prezzemolo q.b.","sale q.b."],"steps":["Pulisci i funghi e tagliali a fette.","Cuocili in padella con olio e aglio a fuoco vivace per 12 minuti.","Sala e aggiungi il prezzemolo."],"notes":""},{"id":"base-melanzane-alla-parmigiana","title":"Melanzane alla parmigiana","category":"Piatti unici","servings":6,"servingsUnit":"porzioni","prepMin":40,"cookMin":40,"restMin":15,"difficulty":"media","tags":["forno","vegetariano"],"ingredients":["1,2 kg melanzane","700 g passata di pomodoro","300 g mozzarella","100 g parmigiano grattugiato","1 spicchio d'aglio","olio per friggere q.b.","basilico q.b.","sale q.b."],"steps":["Taglia le melanzane a fette, salale e lasciale spurgare 30 minuti, poi asciugale e friggile.","Cuoci la passata con aglio, sale e basilico per 15 minuti.","In una teglia alterna sugo, melanzane, mozzarella e parmigiano.","Cuoci a 180 °C per 40 minuti e lascia riposare 15 minuti."],"notes":"Versione leggera: griglia le melanzane invece di friggerle."},{"id":"base-cavolfiore-gratinato","title":"Cavolfiore gratinato","category":"Contorni","servings":4,"servingsUnit":"porzioni","prepMin":15,"cookMin":25,"restMin":null,"difficulty":"facile","tags":["forno","vegetariano"],"ingredients":["1 cavolfiore","300 ml besciamella","50 g parmigiano grattugiato","30 g pangrattato","sale q.b."],"steps":["Dividi il cavolfiore in cimette e lessalo per 8 minuti.","Mettilo in una pirofila con la besciamella.","Copri con parmigiano e pangrattato e gratina a 200 °C per 25 minuti."],"notes":""},{"id":"base-bruschette-al-pomodoro","title":"Bruschette al pomodoro","category":"Antipasti","servings":4,"servingsUnit":"porzioni","prepMin":10,"cookMin":5,"restMin":null,"difficulty":"facile","tags":["veloce","vegano"],"ingredients":["8 fette di pane casereccio","4 pomodori","1 spicchio d'aglio","4 cucchiai di olio extravergine","basilico q.b.","sale q.b."],"steps":["Taglia i pomodori a cubetti e condiscili con olio, sale e basilico.","Tosta il pane in forno o sulla griglia per 5 minuti.","Strofina l'aglio sul pane caldo e distribuisci i pomodori."],"notes":""},{"id":"base-tagliere-di-salumi-e-formaggi","title":"Tagliere di salumi e formaggi","category":"Antipasti","servings":4,"servingsUnit":"porzioni","prepMin":15,"cookMin":null,"restMin":null,"difficulty":"facile","tags":["aperitivo"],"ingredients":["100 g prosciutto crudo","100 g salame","100 g mortadella","150 g pecorino","150 g formaggio stagionato","100 g olive","1 confezione di grissini"],"steps":["Disponi salumi e formaggi su un tagliere, alternando colori e forme.","Completa con olive e grissini."],"notes":"Aggiungi miele o marmellata per accompagnare i formaggi."},{"id":"base-hummus-di-ceci","title":"Hummus di ceci","category":"Antipasti","servings":4,"servingsUnit":"porzioni","prepMin":10,"cookMin":null,"restMin":null,"difficulty":"facile","tags":["vegano"],"ingredients":["480 g ceci lessati","2 cucchiai di tahina","1 limone","1 spicchio d'aglio","4 cucchiai di olio extravergine","cumino q.b.","sale q.b."],"steps":["Frulla ceci, tahina, succo di limone, aglio e sale aggiungendo l'olio a filo.","Allunga con poca acqua fredda fino alla consistenza che preferisci.","Servi con olio, cumino e paprika."],"notes":""},{"id":"base-pizza-margherita","title":"Pizza margherita","category":"Pizze e lievitati","servings":2,"servingsUnit":"porzioni","prepMin":20,"cookMin":12,"restMin":240,"difficulty":"media","tags":["lievitati","vegetariano"],"ingredients":["300 g farina","200 ml acqua","3 g lievito di birra secco","8 g sale","200 g passata di pomodoro","200 g mozzarella","2 cucchiai di olio extravergine","basilico q.b."],"steps":["Sciogli il lievito nell'acqua, aggiungi la farina e poi il sale e impasta per 10 minuti.","Lascia lievitare coperto per 4 ore, finché raddoppia.","Stendi l'impasto in teglia unta e condisci con passata, sale e olio.","Cuoci a 250 °C per 7 minuti, aggiungi la mozzarella e cuoci altri 5 minuti. Completa con basilico."],"notes":""},{"id":"base-focaccia","title":"Focaccia","category":"Pizze e lievitati","servings":6,"servingsUnit":"porzioni","prepMin":20,"cookMin":25,"restMin":240,"difficulty":"media","tags":["lievitati","vegano"],"ingredients":["500 g farina","350 ml acqua","5 g lievito di birra secco","10 g sale","60 ml olio extravergine","sale grosso q.b.","rosmarino q.b."],"steps":["Impasta farina, acqua e lievito, poi aggiungi sale e metà olio e lavora per 10 minuti.","Lascia lievitare per 3 ore, poi stendi in teglia unta e lascia lievitare 1 ora.","Fai le fossette con le dita, condisci con olio, acqua, sale grosso e rosmarino.","Cuoci a 230 °C per 25 minuti."],"notes":""},{"id":"base-piadina-romagnola","title":"Piadina romagnola","category":"Pane","servings":4,"servingsUnit":"porzioni","prepMin":15,"cookMin":10,"restMin":30,"difficulty":"facile","tags":["veloce"],"ingredients":["400 g farina","150 ml acqua","60 g strutto","1 cucchiaino di bicarbonato","8 g sale"],"steps":["Impasta tutti gli ingredienti fino a ottenere un panetto liscio e lascia riposare 30 minuti.","Dividi in 4 e stendi dischi sottili.","Cuoci in padella ben calda per 2 minuti per lato."],"notes":"Al posto dello strutto puoi usare 50 ml di olio extravergine."},{"id":"base-pane-fatto-in-casa","title":"Pane fatto in casa","category":"Pane","servings":8,"servingsUnit":"porzioni","prepMin":20,"cookMin":40,"restMin":300,"difficulty":"media","tags":["lievitati","vegano"],"ingredients":["500 g farina","330 ml acqua","5 g lievito di birra secco","10 g sale"],"steps":["Mescola farina, acqua e lievito, aggiungi il sale e impasta per 10 minuti.","Lascia lievitare 3 ore, poi forma la pagnotta e lascia lievitare ancora 2 ore.","Fai un taglio sulla superficie e cuoci a 230 °C per 40 minuti con una ciotola d'acqua nel forno."],"notes":""},{"id":"base-torta-di-mele","title":"Torta di mele","category":"Dolci","servings":8,"servingsUnit":"porzioni","prepMin":20,"cookMin":45,"restMin":null,"difficulty":"facile","tags":["forno","merenda"],"ingredients":["3 mele","250 g farina","150 g zucchero","3 uova","100 g burro fuso","100 ml latte","1 bustina di lievito per dolci","1 limone"],"steps":["Sbatti uova e zucchero finché sono spumosi.","Aggiungi burro fuso, latte e la scorza di limone, poi farina e lievito setacciati.","Versa in uno stampo imburrato e copri con le mele a fettine.","Cuoci a 180 °C per 45 minuti."],"notes":""},{"id":"base-tiramisu","title":"Tiramisù","category":"Dolci","servings":8,"servingsUnit":"porzioni","prepMin":30,"cookMin":null,"restMin":240,"difficulty":"media","tags":["classico","senza forno"],"ingredients":["500 g mascarpone","4 uova","100 g zucchero","300 g savoiardi","300 ml caffè","cacao amaro q.b."],"steps":["Monta i tuorli con lo zucchero, poi unisci il mascarpone.","Monta gli albumi a neve e incorporali delicatamente alla crema.","Bagna i savoiardi nel caffè freddo e alternali alla crema in una pirofila.","Spolvera di cacao e lascia in frigo almeno 4 ore."],"notes":""},{"id":"base-ciambellone","title":"Ciambellone","category":"Dolci","servings":10,"servingsUnit":"porzioni","prepMin":15,"cookMin":45,"restMin":null,"difficulty":"facile","tags":["merenda","colazione"],"ingredients":["300 g farina","200 g zucchero","4 uova","120 ml olio di semi","150 ml latte","1 bustina di lievito per dolci","1 limone"],"steps":["Monta uova e zucchero per 5 minuti.","Aggiungi olio, latte e scorza di limone, poi farina e lievito setacciati.","Versa nello stampo da ciambella unto e infarinato.","Cuoci a 170 °C per 45 minuti."],"notes":""},{"id":"base-crostata-di-marmellata","title":"Crostata di marmellata","category":"Dolci","servings":8,"servingsUnit":"porzioni","prepMin":25,"cookMin":35,"restMin":30,"difficulty":"media","tags":["forno"],"ingredients":["300 g farina","150 g burro freddo","120 g zucchero","1 uovo","1 tuorlo","1 limone","350 g marmellata"],"steps":["Lavora velocemente farina, burro a pezzi e zucchero, poi aggiungi uova e scorza di limone.","Avvolgi la frolla nella pellicola e lascia in frigo 30 minuti.","Stendi due terzi in uno stampo, farcisci con la marmellata e fai le strisce con il resto.","Cuoci a 180 °C per 35 minuti."],"notes":""},{"id":"base-biscotti-al-burro","title":"Biscotti al burro","category":"Dolci","servings":30,"servingsUnit":"porzioni","prepMin":20,"cookMin":12,"restMin":30,"difficulty":"facile","tags":["merenda"],"ingredients":["250 g farina","125 g burro","100 g zucchero","1 uovo","1 bustina di vanillina"],"steps":["Impasta tutti gli ingredienti fino a ottenere una frolla liscia e lasciala riposare in frigo 30 minuti.","Stendila a 5 mm e ritaglia i biscotti.","Cuoci a 180 °C per 12 minuti, finché sono appena dorati."],"notes":""},{"id":"base-panna-cotta","title":"Panna cotta","category":"Dolci","servings":6,"servingsUnit":"porzioni","prepMin":10,"cookMin":5,"restMin":240,"difficulty":"facile","tags":["senza forno"],"ingredients":["500 ml panna fresca","80 g zucchero","8 g gelatina in fogli","1 bacca di vaniglia"],"steps":["Ammolla la gelatina in acqua fredda per 10 minuti.","Scalda panna, zucchero e vaniglia senza far bollire, poi togli dal fuoco e sciogli la gelatina strizzata.","Versa negli stampini e lascia in frigo almeno 4 ore."],"notes":"Servi con salsa ai frutti di bosco, caramello o cioccolato."},{"id":"base-salame-di-cioccolato","title":"Salame di cioccolato","category":"Dolci","servings":8,"servingsUnit":"porzioni","prepMin":20,"cookMin":null,"restMin":240,"difficulty":"facile","tags":["senza forno"],"ingredients":["200 g biscotti secchi","100 g burro","100 g zucchero","2 uova","50 g cacao amaro"],"steps":["Sbriciola grossolanamente i biscotti.","Sbatti uova e zucchero, aggiungi il burro morbido e il cacao.","Unisci i biscotti, forma un salame e avvolgilo nella carta forno.","Lascia in frigo almeno 4 ore."],"notes":""},{"id":"base-muffin-al-cioccolato","title":"Muffin al cioccolato","category":"Dolci","servings":12,"servingsUnit":"porzioni","prepMin":15,"cookMin":20,"restMin":null,"difficulty":"facile","tags":["merenda"],"ingredients":["250 g farina","150 g zucchero","2 uova","100 ml olio di semi","200 ml latte","30 g cacao amaro","100 g gocce di cioccolato","1 bustina di lievito per dolci"],"steps":["Mescola gli ingredienti secchi in una ciotola e quelli liquidi in un'altra.","Uniscili mescolando poco, giusto per amalgamare, poi aggiungi le gocce di cioccolato.","Riempi i pirottini per due terzi e cuoci a 180 °C per 20 minuti."],"notes":""},{"id":"base-crepes","title":"Crêpes","category":"Dolci","servings":4,"servingsUnit":"porzioni","prepMin":10,"cookMin":15,"restMin":30,"difficulty":"facile","tags":["colazione"],"ingredients":["125 g farina","250 ml latte","2 uova","20 g burro","1 pizzico di sale"],"steps":["Sbatti uova e latte, aggiungi la farina e il sale e mescola fino a eliminare i grumi.","Lascia riposare 30 minuti.","Cuoci un mestolino di pastella alla volta in padella imburrata per 1 minuto per lato."],"notes":"Farcisci con crema di nocciole, marmellata o, in versione salata, prosciutto e formaggio."},{"id":"base-pancake","title":"Pancake","category":"Colazione","servings":4,"servingsUnit":"porzioni","prepMin":10,"cookMin":15,"restMin":null,"difficulty":"facile","tags":["colazione"],"ingredients":["200 g farina","250 ml latte","2 uova","30 g zucchero","30 g burro fuso","1 cucchiaino di lievito per dolci"],"steps":["Mescola farina, zucchero e lievito.","Sbatti uova, latte e burro fuso e uniscili agli ingredienti secchi.","Cuoci un mestolino alla volta in padella antiaderente per 2 minuti per lato."],"notes":"Servi con sciroppo d'acero, miele o frutta fresca."},{"id":"base-porridge","title":"Porridge","category":"Colazione","servings":1,"servingsUnit":"porzioni","prepMin":2,"cookMin":5,"restMin":null,"difficulty":"facile","tags":["colazione","veloce"],"ingredients":["50 g fiocchi d'avena","250 ml latte","1 cucchiaino di miele","1 banana"],"steps":["Cuoci l'avena nel latte a fuoco basso per 5 minuti, mescolando.","Versa nella ciotola e completa con miele e banana a fette."],"notes":""},{"id":"base-yogurt-con-frutta-e-granola","title":"Yogurt con frutta e granola","category":"Colazione","servings":1,"servingsUnit":"porzioni","prepMin":5,"cookMin":null,"restMin":null,"difficulty":"facile","tags":["colazione","veloce"],"ingredients":["150 g yogurt greco","40 g granola","100 g frutti di bosco","1 cucchiaino di miele"],"steps":["Versa lo yogurt in una ciotola.","Aggiungi la frutta, la granola e un filo di miele."],"notes":""},{"id":"base-toast-prosciutto-e-formaggio","title":"Toast prosciutto e formaggio","category":"Piatti unici","servings":2,"servingsUnit":"porzioni","prepMin":5,"cookMin":5,"restMin":null,"difficulty":"facile","tags":["veloce"],"ingredients":["4 fette di pane in cassetta","4 fette di prosciutto cotto","4 fette di formaggio","10 g burro"],"steps":["Componi i toast con prosciutto e formaggio.","Scaldali in una tostiera o in padella con poco burro per 2-3 minuti per lato."],"notes":""},{"id":"base-macedonia-di-frutta","title":"Macedonia di frutta","category":"Dolci","servings":4,"servingsUnit":"porzioni","prepMin":20,"cookMin":null,"restMin":30,"difficulty":"facile","tags":["estate","vegano"],"ingredients":["2 mele","2 pere","2 banane","200 g fragole","2 kiwi","1 arancia","1 limone","2 cucchiai di zucchero"],"steps":["Taglia tutta la frutta a pezzetti.","Condisci con succo di arancia e limone e lo zucchero.","Lascia riposare in frigo 30 minuti."],"notes":""},{"id":"base-sugo-di-pomodoro","title":"Sugo di pomodoro","category":"Salse e condimenti","servings":4,"servingsUnit":"porzioni","prepMin":5,"cookMin":20,"restMin":null,"difficulty":"facile","tags":["base","vegano"],"ingredients":["700 g passata di pomodoro","1 spicchio d'aglio","3 cucchiai di olio extravergine","basilico q.b.","sale q.b."],"steps":["Scalda olio e aglio, aggiungi la passata e il sale.","Cuoci a fuoco dolce per 20 minuti.","Togli l'aglio e aggiungi il basilico."],"notes":""},{"id":"base-besciamella","title":"Besciamella","category":"Salse e condimenti","servings":4,"servingsUnit":"porzioni","prepMin":5,"cookMin":10,"restMin":null,"difficulty":"facile","tags":["base","vegetariano"],"ingredients":["500 ml latte","40 g burro","40 g farina","noce moscata q.b.","sale q.b."],"steps":["Sciogli il burro, aggiungi la farina e cuoci per 1 minuto mescolando.","Versa il latte caldo poco alla volta, mescolando con la frusta.","Cuoci per 8 minuti finché si addensa. Regola di sale e noce moscata."],"notes":""},{"id":"base-ragu-alla-bolognese","title":"Ragù alla bolognese","category":"Salse e condimenti","servings":6,"servingsUnit":"porzioni","prepMin":20,"cookMin":120,"restMin":null,"difficulty":"media","tags":["base"],"ingredients":["300 g macinato di manzo","200 g macinato di maiale","1 carota","1 costa di sedano","1 cipolla","150 ml vino rosso","700 g passata di pomodoro","3 cucchiai di olio extravergine","sale q.b."],"steps":["Soffriggi carota, sedano e cipolla tritati nell'olio per 8 minuti.","Aggiungi la carne e rosolala bene, poi sfuma con il vino.","Aggiungi la passata e cuoci coperto a fuoco minimo per 2 ore, mescolando ogni tanto."],"notes":""},{"id":"base-pesto-alla-genovese","title":"Pesto alla genovese","category":"Salse e condimenti","servings":4,"servingsUnit":"porzioni","prepMin":15,"cookMin":null,"restMin":null,"difficulty":"facile","tags":["base","vegetariano"],"ingredients":["50 g basilico","60 g parmigiano grattugiato","20 g pecorino grattugiato","30 g pinoli","1 spicchio d'aglio","100 ml olio extravergine","sale q.b."],"steps":["Frulla basilico, aglio, pinoli e sale con l'olio a scatti, per non scaldare le foglie.","Aggiungi i formaggi e mescola.","Conserva in frigo coperto da un velo d'olio."],"notes":""},{"id":"base-maionese","title":"Maionese","category":"Salse e condimenti","servings":6,"servingsUnit":"porzioni","prepMin":10,"cookMin":null,"restMin":null,"difficulty":"media","tags":["base"],"ingredients":["1 uovo","200 ml olio di semi","1 cucchiaio di succo di limone","sale q.b."],"steps":["Metti uovo, limone e sale nel bicchiere del frullatore a immersione.","Aggiungi l'olio e frulla partendo dal fondo, risalendo lentamente finché si addensa."],"notes":""},{"id":"base-brodo-vegetale","title":"Brodo vegetale","category":"Salse e condimenti","servings":6,"servingsUnit":"porzioni","prepMin":10,"cookMin":60,"restMin":null,"difficulty":"facile","tags":["base","vegano"],"ingredients":["2 carote","2 coste di sedano","1 cipolla","2 pomodori","1 patata","2 l acqua","prezzemolo q.b.","sale q.b."],"steps":["Metti tutte le verdure lavate e tagliate grossolanamente in una pentola con l'acqua fredda.","Porta a bollore e cuoci a fuoco basso per 60 minuti.","Filtra e regola di sale."],"notes":""},{"id":"base-pollo-al-curry","title":"Pollo al curry","category":"Secondi","servings":4,"servingsUnit":"porzioni","prepMin":15,"cookMin":25,"restMin":null,"difficulty":"facile","tags":["speziato"],"ingredients":["600 g petto di pollo","1 cipolla","2 cucchiai di curry","200 ml latte di cocco","2 cucchiai di olio extravergine","sale q.b."],"steps":["Taglia il pollo a cubetti e rosolalo nell'olio con la cipolla tritata per 6 minuti.","Aggiungi il curry e mescola per 1 minuto.","Versa il latte di cocco e cuoci a fuoco medio per 15 minuti."],"notes":"Servilo con riso basmati."},{"id":"base-chili-con-carne","title":"Chili con carne","category":"Piatti unici","servings":4,"servingsUnit":"porzioni","prepMin":15,"cookMin":60,"restMin":null,"difficulty":"facile","tags":["speziato"],"ingredients":["500 g macinato di manzo","480 g fagioli rossi lessati","1 cipolla","1 peperone","400 g pomodori pelati","1 cucchiaino di cumino","1 cucchiaino di peperoncino in polvere","3 cucchiai di olio extravergine","sale q.b."],"steps":["Soffriggi cipolla e peperone a dadini nell'olio per 5 minuti.","Aggiungi la carne e rosolala, poi le spezie.","Unisci i pelati e cuoci per 40 minuti, poi i fagioli e cuoci altri 15 minuti."],"notes":""},{"id":"base-burger-vegetali-di-lenticchie","title":"Burger vegetali di lenticchie","category":"Secondi","servings":4,"servingsUnit":"porzioni","prepMin":20,"cookMin":15,"restMin":null,"difficulty":"facile","tags":["vegano"],"ingredients":["400 g lenticchie lessate","1 carota","1 cipollotto","60 g pangrattato","1 cucchiaino di paprika","3 cucchiai di olio extravergine","sale q.b."],"steps":["Frulla grossolanamente lenticchie, carota grattugiata e cipollotto.","Aggiungi pangrattato, paprika e sale e forma 4 burger.","Cuocili in padella con l'olio per 4 minuti per lato."],"notes":""},{"id":"base-couscous-con-verdure","title":"Couscous con verdure","category":"Piatti unici","servings":4,"servingsUnit":"porzioni","prepMin":15,"cookMin":15,"restMin":null,"difficulty":"facile","tags":["vegano"],"ingredients":["300 g couscous","2 zucchine","1 peperone","1 carota","1 cipolla","240 g ceci lessati","4 cucchiai di olio extravergine","menta q.b.","sale q.b."],"steps":["Versa sul couscous la stessa quantità di acqua bollente salata, copri e lascia riposare 5 minuti, poi sgrana con una forchetta.","Cuoci le verdure a dadini in padella con olio e cipolla per 10 minuti.","Unisci verdure, ceci e couscous e completa con menta."],"notes":""},{"id":"base-crocchette-di-patate","title":"Crocchette di patate","category":"Antipasti","servings":4,"servingsUnit":"porzioni","prepMin":30,"cookMin":10,"restMin":null,"difficulty":"media","tags":["fritto"],"ingredients":["800 g patate","1 uovo","60 g parmigiano grattugiato","120 g pangrattato","2 uova per la panatura","olio per friggere q.b.","noce moscata q.b.","sale q.b."],"steps":["Lessa le patate per 25 minuti e schiacciale.","Impasta con uovo, parmigiano, sale e noce moscata e forma delle crocchette.","Passale nell'uovo sbattuto e nel pangrattato e friggile in olio caldo per 3-4 minuti."],"notes":""},{"id":"base-polenta","title":"Polenta","category":"Piatti unici","servings":4,"servingsUnit":"porzioni","prepMin":5,"cookMin":45,"restMin":null,"difficulty":"facile","tags":["inverno"],"ingredients":["300 g farina di mais","1,2 l acqua","10 g sale","40 g burro"],"steps":["Porta a bollore l'acqua salata.","Versa la farina a pioggia mescolando con la frusta.","Cuoci a fuoco basso per 45 minuti, mescolando spesso, poi aggiungi il burro."],"notes":"Ottima con spezzatino, funghi trifolati o formaggi."},{"id":"base-zuppa-di-lenticchie","title":"Zuppa di lenticchie","category":"Primi","servings":4,"servingsUnit":"porzioni","prepMin":10,"cookMin":40,"restMin":null,"difficulty":"facile","tags":["vegano","inverno"],"ingredients":["300 g lenticchie","1 carota","1 costa di sedano","1 cipolla","2 cucchiai di concentrato di pomodoro","1,2 l brodo vegetale","3 cucchiai di olio extravergine","alloro q.b.","sale q.b."],"steps":["Soffriggi carota, sedano e cipolla tritati nell'olio per 5 minuti.","Aggiungi lenticchie, concentrato, alloro e brodo.","Cuoci a fuoco basso per 40 minuti, finché le lenticchie sono morbide."],"notes":""},{"id":"base-pasta-al-forno","title":"Pasta al forno","category":"Primi","servings":6,"servingsUnit":"porzioni","prepMin":30,"cookMin":30,"restMin":null,"difficulty":"facile","tags":["forno"],"ingredients":["500 g rigatoni","400 g macinato misto","700 g passata di pomodoro","250 g mozzarella","80 g parmigiano grattugiato","1 cipolla","3 cucchiai di olio extravergine","sale q.b."],"steps":["Prepara un sugo di carne rosolando cipolla e macinato nell'olio, poi aggiungi la passata e cuoci per 20 minuti.","Lessa la pasta molto al dente e condiscila con il sugo.","Versa in una teglia alternando mozzarella a cubetti e parmigiano.","Cuoci a 200 °C per 30 minuti."],"notes":""},{"id":"base-spaghetti-alle-vongole","title":"Spaghetti alle vongole","category":"Primi","servings":4,"servingsUnit":"porzioni","prepMin":20,"cookMin":15,"restMin":null,"difficulty":"media","tags":["pesce"],"ingredients":["320 g spaghetti","1 kg vongole","2 spicchi d'aglio","1 peperoncino","80 ml vino bianco","4 cucchiai di olio extravergine","prezzemolo q.b."],"steps":["Fai spurgare le vongole in acqua salata per 1 ora e sciacquale.","Scalda olio, aglio e peperoncino, aggiungi le vongole e il vino e copri finché si aprono, circa 4 minuti.","Cuoci gli spaghetti al dente e saltali con le vongole e il loro liquido. Completa con prezzemolo."],"notes":""},{"id":"base-pasta-salmone-e-panna","title":"Pasta salmone e panna","category":"Primi","servings":4,"servingsUnit":"porzioni","prepMin":10,"cookMin":12,"restMin":null,"difficulty":"facile","tags":["veloce","pesce"],"ingredients":["320 g farfalle","150 g salmone affumicato","200 ml panna da cucina","1 scalogno","20 g burro","erba cipollina q.b.","sale q.b."],"steps":["Fai appassire lo scalogno nel burro, aggiungi il salmone a striscioline e cuoci 1 minuto.","Unisci la panna e scalda per 2 minuti.","Lessa la pasta, scolala e condiscila con la salsa e l'erba cipollina."],"notes":""},{"id":"base-penne-panna-e-prosciutto","title":"Penne panna e prosciutto","category":"Primi","servings":4,"servingsUnit":"porzioni","prepMin":5,"cookMin":12,"restMin":null,"difficulty":"facile","tags":["veloce"],"ingredients":["320 g penne","150 g prosciutto cotto a dadini","200 ml panna da cucina","20 g burro","40 g parmigiano grattugiato","sale q.b."],"steps":["Rosola il prosciutto nel burro per 2 minuti.","Aggiungi la panna e scalda per 2 minuti.","Condisci la pasta con la salsa e il parmigiano."],"notes":""},{"id":"base-pasta-con-broccoli","title":"Pasta con broccoli","category":"Primi","servings":4,"servingsUnit":"porzioni","prepMin":10,"cookMin":15,"restMin":null,"difficulty":"facile","tags":["vegano"],"ingredients":["320 g orecchiette","500 g broccoli","2 spicchi d'aglio","1 peperoncino","4 cucchiai di olio extravergine","sale q.b."],"steps":["Lessa le cimette di broccolo in acqua salata per 5 minuti, poi aggiungi la pasta nella stessa acqua.","Intanto scalda olio, aglio e peperoncino in padella.","Scola pasta e broccoli e saltali nell'olio, schiacciando un po' i broccoli."],"notes":""},{"id":"base-pasta-al-burro-e-parmigiano","title":"Pasta al burro e parmigiano","category":"Primi","servings":2,"servingsUnit":"porzioni","prepMin":2,"cookMin":10,"restMin":null,"difficulty":"facile","tags":["veloce","vegetariano"],"ingredients":["160 g pasta","30 g burro","40 g parmigiano grattugiato","sale q.b."],"steps":["Lessa la pasta in acqua salata.","Scolala tenendo un po' d'acqua di cottura.","Mescola con burro, parmigiano e poca acqua fino a renderla cremosa."],"notes":""},{"id":"base-fettuccine-al-ragu-bianco","title":"Fettuccine al ragù bianco","category":"Primi","servings":4,"servingsUnit":"porzioni","prepMin":15,"cookMin":40,"restMin":null,"difficulty":"media","tags":["classico"],"ingredients":["400 g fettuccine","400 g salsiccia","1 cipolla","1 carota","100 ml vino bianco","300 ml brodo vegetale","3 cucchiai di olio extravergine","parmigiano q.b.","sale q.b."],"steps":["Soffriggi cipolla e carota tritate, poi aggiungi la salsiccia sgranata e rosolala.","Sfuma con il vino e cuoci per 30 minuti aggiungendo brodo quando serve.","Condisci la pasta con il ragù e servi con parmigiano."],"notes":""},{"id":"base-spaghetti-alla-puttanesca","title":"Spaghetti alla puttanesca","category":"Primi","servings":4,"servingsUnit":"porzioni","prepMin":10,"cookMin":15,"restMin":null,"difficulty":"facile","tags":["veloce","dispensa"],"ingredients":["320 g spaghetti","400 g pomodori pelati","80 g olive nere","1 cucchiaio di capperi","4 filetti di acciuga","2 spicchi d'aglio","1 peperoncino","3 cucchiai di olio extravergine","prezzemolo q.b."],"steps":["Scalda olio, aglio e peperoncino e sciogli le acciughe a fuoco basso.","Aggiungi i pelati schiacciati, le olive e i capperi e cuoci per 10 minuti.","Cuoci gli spaghetti al dente e saltali nel sugo. Completa con prezzemolo."],"notes":""},{"id":"base-pasta-alla-gricia","title":"Pasta alla gricia","category":"Primi","servings":4,"servingsUnit":"porzioni","prepMin":10,"cookMin":15,"restMin":null,"difficulty":"media","tags":["classico"],"ingredients":["320 g rigatoni","150 g guanciale","70 g pecorino romano grattugiato","pepe nero q.b."],"steps":["Rosola il guanciale a listarelle in padella senza olio per 8 minuti.","Cuoci la pasta e scolala al dente tenendo l'acqua di cottura.","Saltala con il guanciale e un mestolo d'acqua, poi a fuoco spento aggiungi pecorino e pepe mescolando fino a ottenere una crema."],"notes":""},{"id":"base-torta-salata-spinaci-e-ricotta","title":"Torta salata spinaci e ricotta","category":"Piatti unici","servings":6,"servingsUnit":"porzioni","prepMin":20,"cookMin":40,"restMin":null,"difficulty":"facile","tags":["forno","vegetariano"],"ingredients":["1 rotolo di pasta sfoglia","500 g spinaci","250 g ricotta","2 uova","50 g parmigiano grattugiato","noce moscata q.b.","sale q.b."],"steps":["Cuoci gli spinaci in padella per 5 minuti, strizzali bene e tritali.","Mescolali con ricotta, uova, parmigiano, sale e noce moscata.","Stendi la sfoglia in una teglia, versa il ripieno e ripiega i bordi.","Cuoci a 180 °C per 40 minuti."],"notes":""},{"id":"base-insalata-di-farro","title":"Insalata di farro","category":"Piatti unici","servings":4,"servingsUnit":"porzioni","prepMin":15,"cookMin":25,"restMin":null,"difficulty":"facile","tags":["estate","vegetariano"],"ingredients":["300 g farro","250 g pomodorini","1 zucchina","150 g feta","4 cucchiai di olio extravergine","basilico q.b.","sale q.b."],"steps":["Lessa il farro in acqua salata per 25 minuti, scolalo e raffreddalo.","Taglia pomodorini, zucchina cruda a dadini e feta.","Unisci tutto e condisci con olio, sale e basilico."],"notes":""},{"id":"base-fagioli-all-uccelletto","title":"Fagioli all'uccelletto","category":"Contorni","servings":4,"servingsUnit":"porzioni","prepMin":5,"cookMin":20,"restMin":null,"difficulty":"facile","tags":["tradizionale","vegano"],"ingredients":["480 g fagioli cannellini lessati","300 g passata di pomodoro","2 spicchi d'aglio","4 foglie di salvia","3 cucchiai di olio extravergine","sale q.b."],"steps":["Scalda olio, aglio e salvia.","Aggiungi la passata e cuoci per 5 minuti, poi unisci i fagioli.","Cuoci a fuoco basso per 15 minuti."],"notes":""},{"id":"base-pollo-al-limone","title":"Pollo al limone","category":"Secondi","servings":4,"servingsUnit":"porzioni","prepMin":10,"cookMin":15,"restMin":null,"difficulty":"facile","tags":["veloce"],"ingredients":["600 g petto di pollo","50 g farina","2 limoni","30 g burro","1 cucchiaio di olio extravergine","prezzemolo q.b.","sale q.b."],"steps":["Taglia il pollo a bocconcini e infarinalo.","Rosolalo in padella con burro e olio per 8 minuti.","Aggiungi il succo dei limoni e un po' d'acqua e fai addensare per 3 minuti. Completa con prezzemolo."],"notes":""}];
